code.solution:
import math

def relu(z):
    return float(max(0.0, z))

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def neuron(x, w, b, activation):
    z = sum(xi * wi for xi, wi in zip(x, w)) + b
    a = relu(z) if activation == "relu" else sigmoid(z)
    return round(a, 3)

