code.solution:
def gd_step(w, b, xs, ys, lr):
    n = len(xs)
    errs = [w * x + b - y for x, y in zip(xs, ys)]
    dw = 2 / n * sum(e * x for e, x in zip(errs, xs))
    db = 2 / n * sum(errs)
    return (round(w - lr * dw, 4), round(b - lr * db, 4))

